// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }
    function testRegression_property() public {
        address user = address(0x1234);

        vm.deal(user, 1 ether);

        vm.prank(user);
        (bool success, ) = address(c).call{value: 1 wei}("");
        assertTrue(success);

        uint256 userBalance = c.balanceOf(user);

        assertEq(userBalance, 1000e18);
    }
}
